actions.script:
if (!experiment) { ec.message.addError(ec.l10n.localize('Experiment not found')); return }
canEdit = ec.user.hasPermission('MONITOR_EVAL'); canRun = ec.user.hasPermission('MONITOR_EVAL_RUN')
const num = v => v == null ? null : v.toNumber ? v.toNumber() : Number(v)
const find = (n, c) => Array.from(ec.entity.find(n).condition(c).disableAuthz().list())
const items = {}; for (const i of find('moqui.agent.AgentDatasetItem', {datasetId: experiment.datasetId})) items[i.itemId] = i
const scorers = {}; for (const s of find('moqui.agent.AgentScorer', {})) scorers[s.scorerId] = s
humanScorers = Object.values(scorers).filter(s => s.scorerTypeEnumId === 'AgstHuman').map(s => ({value: s.scorerId, label: s.scorerName || s.scorerId}))
const byResult = {}; for (const s of find('moqui.agent.AgentScore', {experimentId})) (byResult[s.resultId] = byResult[s.resultId] || []).push(s)
const clip = (t, n) => { t = String(t || ''); return t.length > n ? t.slice(0, n) + '…' : t }
resultRows = find('moqui.agent.AgentExperimentResult', {experimentId}).sort((a, b) => String(a.itemId).localeCompare(String(b.itemId)) || num(a.trialNum) - num(b.trialNum)).map(r => {
    const item = items[r.itemId] || {}, scores = byResult[r.resultId] || []
    return Object.assign(r.getMap(), {input: clip(item.inputText, 300), expected: clip(item.groundTruth, 300), output: clip(r.outputText || r.errorText, 600),
        scores: scores.map(s => (scorers[s.scorerId]?.scorerName || s.scorerId) + ': ' + (s.score == null ? 'error ' + clip(s.errorText, 80) : num(s.score).toFixed(2) + (s.passed === 'Y' ? ' ✓' : ' ✗') + (s.reason ? ' — ' + clip(s.reason, 160) : ''))).join('\n')})
})
const scorerStats = {}
for (const s of find('moqui.agent.AgentScore', {experimentId})) { if (s.score == null) continue; const st = scorerStats[s.scorerId] = scorerStats[s.scorerId] || {n: 0, sum: 0, pass: 0}; st.n++; st.sum += num(s.score); if (s.passed === 'Y') st.pass++ }
scorerRows = Object.entries(scorerStats).map(([id, st]) => ({scorerName: scorers[id]?.scorerName || id, count: st.n, mean: (st.sum / st.n).toFixed(2), pass: Math.round(st.pass / st.n * 100) + '%'}))
summary = (experiment.experimentName || experimentId) + ' · ' + (experiment.agentId || experiment.serviceName) + ' · dataset ' + experiment.datasetId + ' v' + experiment.datasetVersion + ' · ' + (ec.entity.find('moqui.basic.StatusItem').condition({statusId: experiment.statusId}).disableAuthz().one()?.description || experiment.statusId)
    + ' · ' + ((experiment.doneCount || 0) + (experiment.failedCount || 0)) + '/' + (experiment.resultCount || 0) + ' done'
    + (experiment.meanScore == null ? '' : ' · mean ' + num(experiment.meanScore).toFixed(2) + ' · passed ' + Math.round(num(experiment.passRate) * 100) + '%')
    + (experiment.cost == null ? '' : ' · cost ' + num(experiment.cost).toFixed(4))
running = experiment.statusId === 'EvRunning'
